interface NotesDepot {
    fun toutes(): List<String>
    fun ajouter(note: String)
}

class FakeNotesDepot : NotesDepot {
    private val notes = mutableListOf<String>()
    override fun toutes() = notes.toList()
    override fun ajouter(note: String) {
        notes += note
    }
}

class AjouterNote(private val depot: NotesDepot) {
    fun executer(texte: String): Boolean {
        val note = texte.trim()
        if (note.isEmpty()) return false
        depot.ajouter(note)
        return true
    }
}

fun main() {
    val depot = FakeNotesDepot()
    val ajouter = AjouterNote(depot)

    println(ajouter.executer("  Acheter du thé  "))
    println(ajouter.executer("   "))
    println(depot.toutes())
}

