data class Mesure(val nom: String, val valeur: Int, val limite: Int)

fun main() {
    val mesures = listOf(
        Mesure("Démarrage (ms)", 820, 1000),
        Mesure("Taille (Mo)", 41, 30),
    )

    mesures.forEach {
        val etat = if (it.valeur <= it.limite) "ok" else "dépassé"
        println("${it.nom} : $etat")
    }
}

